function trdMigV(k,lg,v){if(typeof v!='string')return v;
 const g=TRD_MIG[k]&&TRD_MIG[k][lg];if(g&&v.includes(g[0]))v=v.replace(g[0],g[1]);
 const n=TRD_NL[lg];
 if(n&&k=='expOne'&&v.includes(n[1])&&!v.includes('{NIGHTSA}'))v=v.replace(n[1],'{NIGHTSA}');
 if(n&&k=='expMulti'){if(v.includes(n[0])&&!v.includes('{NIGHTSA}'))v=v.replace(n[0],'{NIGHTSA}');if(v.includes(n[1])&&!v.includes('{NIGHTSB}'))v=v.replace(n[1],'{NIGHTSB}');
  if(!v.includes('{THIRDV}')&&v.includes('\n{SECOND}\n'))v=v.replace('\n{SECOND}\n','\n{SECOND}\n{THIRDV}\n')}
 return v}
/* a saved availability text without the dates (checked once): the old fixed month becomes {UNTIL} and {DATES} follows that sentence */
function trdMigD(k,lg,v){if(typeof v!='string')return v;
 if((k=='manual'||k=='promo')&&!v.includes('{DATES}')&&!/^\s*\*\s/m.test(v)){const ls=v.split('\n');let i=ls.findIndex(z=>z.includes('{UNTIL}'));
  if(i<0){const u=TRD_UNT[lg];if(u){i=ls.findIndex(z=>z.includes(u));if(i>=0)ls[i]=ls[i].replace(u,lg=='tr'?'{UNTIL} tarihine':'{UNTIL}')}}
  if(i>=0){ls.splice(i+1,0,'{DATES}');v=ls.join('\n')}}
 return v}
