const trdTabs=[['t','Treatments'],['i','Patient Explanations'],['s','Settings & Criteria'],['m','Message Templates']];
const trdX=new Set();
function trdFlash(m,bad){const e=$('trdm');if(!e||trdPend)return;e.className='np min-h-[1.25rem] text-xs font-bold '+(bad?'text-red-600':'text-emerald-700');e.textContent=m===''?'':(m||ti('Saved ✓'));clearTimeout(trdFlash.t);trdFlash.t=setTimeout(()=>{const x=$('trdm');if(x&&!trdPend)x.textContent=''},3000)}
function rTRD(){
 $('trdtb').innerHTML=trdTabs.map(([k,l])=>`<button type="button" onclick="trdTab='${k}';rTRD()" class="${trdTab==k?'g':'bg-slate-100 text-slate-700'} rounded px-3 py-1.5 text-xs font-bold uppercase">${l}</button>`).join('');
 $('trdb').innerHTML=trdTab=='t'?trdTreat():trdTab=='i'?trdInfo():trdTab=='s'?trdSettings():trdTpl();
 if(trdTab=='t')trdFilt();trdPendShow()}
const trdSum=()=>{const a=trdAll();return ti('{0} treatments · {1} without a price',a.length,a.filter(x=>!trdOK(x.c,x.t)).length)};
const trdStat=(c,t)=>!trdOK(c,t)?'Price not set':c.kind=='h'?'':(t.x<t.l?'Normal price is lower than Least price':!(t.h>0)?'High price not set (the Normal price is used)':t.h<t.x?'High price is lower than Normal price':'');
function trdRow(c,t){
 const n=(f,v)=>`<td><input type="number" step="any" min="0" value="${v==null?'':v}" onchange="trdI('${t.id}','${f}',this.value)" class="w-24 border rounded p-1 text-xs font-semibold bg-white text-right"></td>`,s=trdStat(c,t),b='bg-slate-200 rounded px-1.5 py-0.5 text-[10px] font-bold';
 return `<tr data-id="${t.id}" data-n="${esc(trdSn(t))}"><td class="whitespace-normal"><input value="${esc(t.n)}" onchange="trdI('${t.id}','n',this.value)" class="w-full min-w-[14rem] border rounded p-1 text-xs font-semibold bg-white"></td>${n('b',t.b)}${n('l',t.l)}${n('x',t.x)}${c.kind=='h'?'':n('h',t.h)}<td class="trds text-[10px] font-bold text-amber-700 whitespace-normal">${s?esc(ti(s)):''}</td><td class="np whitespace-nowrap"><button type="button" title="Move up" onclick="trdMv('${t.id}',-1)" class="${b}">▲</button> <button type="button" title="Move down" onclick="trdMv('${t.id}',1)" class="${b}">▼</button> <button type="button" onclick="trdDel(this,'${t.id}')" class="bg-red-100 text-red-700 rounded px-1.5 py-0.5 text-[10px] font-bold">✕</button> <button type="button" title="Names in other languages and patient explanation" onclick="trdXt('${t.id}')" class="${b}">🌐</button>${c.kind=='h'?'':` <button type="button" title="Photos for the patient (the explanation text is in the Patient Explanations tab)" onclick="EX.editDb('${t.id}')" class="${b}">📝</button>`}</td></tr>`+(trdX.has(t.id)?trdXRow(c,t):'')}
function trdCatH(c){
 const h=c.kind=='h',cols=h?['Hotel','Single','Double','Triple']:['Treatment','Local price (USD)','Least Price','Normal Price','High Price'],bt='bg-slate-700 text-white rounded px-2 py-1 text-[10px] font-bold',ip='border border-slate-600 rounded p-1 text-xs bg-slate-800 text-white';
 return `<div class="rounded-xl border border-slate-200 bg-slate-50 overflow-hidden" data-cat="${c.id}"><div class="np flex flex-wrap items-center gap-2 p-2 bg-slate-900">`
  +`<input value="${esc(c.name)}" onchange="trdC('${c.id}','name',this.value)" placeholder="Category name" class="grow min-w-[10rem] ${ip} font-bold text-[#a08a7c]">`
  +`<select onchange="trdC('${c.id}','kind',this.value)" class="${ip} font-bold"><option value="t"${h?'':' selected'}>Treatments</option><option value="h"${h?' selected':''}>Hotels (per night)</option></select>`
  +`<input value="${esc(c.d||'')}" onchange="trdC('${c.id}','d',this.value)" placeholder="Description (optional)" class="grow min-w-[10rem] ${ip}">`
  +`<button type="button" title="Move up" onclick="trdCatMv('${c.id}',-1)" class="${bt}">▲</button><button type="button" title="Move down" onclick="trdCatMv('${c.id}',1)" class="${bt}">▼</button><button type="button" onclick="trdCatDel(this,'${c.id}')" class="bg-red-600 text-white rounded px-2 py-1 text-[10px] font-bold uppercase">Delete</button></div>`
  +`<div class="overflow-x-auto"><table><thead><tr>${cols.map(x=>`<th>${x}</th>`).join('')}<th></th><th class="np"></th></tr></thead><tbody>${c.items.map(t=>trdRow(c,t)).join('')}</tbody></table></div>`
  +`<div class="np p-2"><button type="button" onclick="trdAdd('${c.id}')" class="bg-slate-200 rounded px-3 py-1.5 text-[10px] font-bold uppercase">+ Add Treatment</button></div></div>`}
function trdTreat(){
 return `<div class="np flex flex-wrap items-end gap-3 text-xs"><div class="grow min-w-[10rem]"><label class="block text-[10px] text-slate-500 font-bold uppercase">Search<input id="trdq" value="${esc(trdQ)}" placeholder="Search treatments…" oninput="trdQ=this.value;trdFilt()" class="block w-full border rounded p-1.5 mt-1 font-bold text-slate-900 normal-case bg-white"></label></div><button type="button" onclick="trdCatAdd()" class="g rounded px-3 py-1.5 font-bold uppercase">+ Add Category</button><span id="trdsum" class="font-bold text-slate-500 pb-2">${esc(trdSum())}</span></div>`
  +`<p class="text-xs text-slate-500">All-on-4, All-on-6 and Zygomatic are built in the Treatment Plan Calculator from the treatments below. Use the 🌐 button of a treatment to give it a package role (implant, crown, bone graft…) so that it appears in the package options.</p>`
  +`<p class="text-xs text-slate-500">Hotels: the Single price is the Least price, the Double price is the Normal price and the Triple price is the High price. The High Price of a treatment is optional; when it is empty the Normal price is used.</p>`
  +`<p class="text-xs text-slate-500">The Ticket Calendar takes its hotel list and the price per night (the Single price) from here.</p>`
  +PDB.cats.map(trdCatH).join('')}
function trdFilt(){const q=(trdQ||'').trim().toLowerCase();
 document.querySelectorAll('#trdb [data-cat]').forEach(cd=>{const cc=PDB.cats.find(c=>c.id==cd.dataset.cat)||{},cn=((cc.name||'')+' '+Object.values(cc.tn||{}).join(' ')).toLowerCase();let any=false;
  cd.querySelectorAll('tbody tr[data-n]').forEach(tr=>{const m=!q||cn.includes(q)||tr.dataset.n.includes(q);tr.classList.toggle('hidden',!m);if(m)any=true;const x=tr.nextElementSibling;if(x&&x.dataset.xid==tr.dataset.id)x.classList.toggle('hidden',!m)});
  cd.classList.toggle('hidden',!!q&&!any)})}
function trdI(id,f,v){const r=trdFind(id);if(!r)return;
 if(f=='n')r.t.n=String(v).replace(/\s+/g,' ').trim()||r.t.n;else{let n=trdNum(v);if(n!=null&&n<0)n=0;r.t[f]=n}
 trdSave();const tr=document.querySelector(`#trdb tr[data-id="${id}"]`);
 if(tr){const s=trdStat(r.c,r.t);tr.querySelector('.trds').textContent=s?ti(s):'';tr.dataset.n=trdSn(r.t);if(f=='n')tr.querySelector('input').value=r.t.n}
 const e=$('trdsum');if(e)e.textContent=trdSum();trdFlash()}
function trdC(id,f,v){const c=PDB.cats.find(x=>x.id==id);if(!c)return;c[f]=f=='kind'?v:String(v).trim()||(f=='name'?c.name:'');trdSave();if(f=='kind'){rTRD()}else trdFlash()}
function trdCatAdd(){const c={id:trdUid(),name:ti('New category'),kind:'t',d:'',tn:{},items:[]};PDB.cats.push(c);trdSave();rTRD();const e=document.querySelector(`#trdb [data-cat="${c.id}"]`);if(e){try{e.scrollIntoView({block:'center'})}catch(x){}const i=e.querySelector('input');if(i)i.select()}}
function trdCatMv(id,d){const i=PDB.cats.findIndex(c=>c.id==id),j=i+d;if(i<0||j<0||j>=PDB.cats.length)return;const t=PDB.cats[i];PDB.cats[i]=PDB.cats[j];PDB.cats[j]=t;trdSave();rTRD()}
function trdTwo(b,txt,go){if(!b.dataset.a){b.dataset.a=1;b.dataset.o=b.textContent;b.textContent='Sure? Click again';setTimeout(()=>{b.dataset.a='';b.textContent=b.dataset.o},3000);return}go()}
function trdCatDel(b,id){trdTwo(b,'Delete',()=>{PDB.cats=PDB.cats.filter(c=>c.id!=id);trdSave();rTRD()})}
function trdAdd(cid){const c=PDB.cats.find(x=>x.id==cid);if(!c)return;const t={id:trdUid(),n:ti('New treatment'),b:null,l:null,x:null,e:[],tn:{}};c.items.push(t);trdSave();rTRD();const i=document.querySelector(`#trdb tr[data-id="${t.id}"] input`);if(i){try{i.scrollIntoView({block:'center'})}catch(x){}i.select()}}
function trdMv(id,d){const r=trdFind(id);if(!r)return;const j=r.i+d,a=r.c.items;if(j<0||j>=a.length)return;const t=a[r.i];a[r.i]=a[j];a[j]=t;trdSave();rTRD()}
function trdDel(b,id){trdTwo(b,'✕',()=>{const r=trdFind(id);if(!r)return;r.c.items.splice(r.i,1);trdSave();rTRD()})}

/* other-language names + patient explanation links (the 🌐 row under a treatment) */
function trdXRow(c,t){
 const ip='w-full border rounded p-1 text-xs font-semibold bg-white',e=(t.e||[]).filter(k=>!trdIDead(k)),
  ch=e.map(k=>`<span class="inline-flex items-center gap-1 bg-slate-100 rounded px-2 py-0.5 text-[10px] font-bold"><span data-notr>${esc(trdIL(k))}</span><button type="button" onclick="trdEd('${t.id}','${k}')" class="text-red-600">✕</button></span>`).join(' '),
  opts=trdIK().filter(k=>!e.includes(k)).map(k=>`<option value="${k}">${esc(trdIL(k))}</option>`).join('');
 return `<tr data-xid="${t.id}" class="np"><td colspan="${c.kind=='h'?6:7}" class="whitespace-normal bg-slate-50"><div class="grid grid-cols-1 md:grid-cols-3 gap-2" data-notr>${LANGS.filter(x=>x[0]!='en').map(([k,n])=>`<label class="block text-[10px] text-slate-500 font-bold">${n}<input value="${esc((t.tn||{})[k]||'')}" placeholder="${esc(t.n)}" ${k=='ar'?'dir="auto" ':''}onchange="trdTnS('${t.id}','${k}',this.value)" class="${ip}"></label>`).join('')}</div>`
  +`<div class="mt-2 flex flex-wrap items-center gap-2 text-[10px] font-bold"><span class="uppercase text-slate-500">Patient explanation</span>${ch||'<span class="text-slate-400 italic font-semibold">None</span>'}<select onchange="trdEa('${t.id}',this.value)" class="border rounded p-1 text-xs bg-white text-slate-900"><option value="">+ Add explanation…</option>${opts}</select></div>`
  +`<div class="mt-2 flex flex-wrap items-center gap-2 text-[10px] font-bold"><span class="uppercase text-slate-500">Package role</span><select onchange="trdPr('${t.id}',this.value)" class="border rounded p-1 text-xs bg-white text-slate-900"><option value="">None</option>${TRD_PR.map(([k,n])=>`<option value="${k}"${t.p==k?' selected':''}>${n}</option>`).join('')}</select></div></td></tr>`}
function trdXr(id){const r=trdFind(id),tr=document.querySelector(`#trdb tr[data-id="${id}"]`);if(!r||!tr)return;tr.dataset.n=trdSn(r.t);const nx=tr.nextElementSibling;if(nx&&nx.dataset.xid==id)nx.remove();if(trdX.has(id))tr.insertAdjacentHTML('afterend',trdXRow(r.c,r.t))}
function trdXt(id){if(trdX.has(id))trdX.delete(id);else trdX.add(id);trdXr(id)}
function trdTnS(id,l,v){const r=trdFind(id);if(!r)return;r.t.tn=r.t.tn||{};v=String(v).replace(/\s+/g,' ').trim();if(v)r.t.tn[l]=v;else delete r.t.tn[l];trdSave();trdXr(id);trdFlash()}
function trdEa(id,k){const r=trdFind(id);if(!r||!k)return;r.t.e=r.t.e||[];if(!r.t.e.includes(k))r.t.e.push(k);trdSave();trdXr(id);trdFlash()}
function trdPr(id,v){const r=trdFind(id);if(!r)return;if(v)r.t.p=v;else delete r.t.p;trdSave();trdXr(id);trdFlash()}
function trdEd(id,k){const r=trdFind(id);if(!r)return;r.t.e=(r.t.e||[]).filter(x=>x!=k);trdSave();trdXr(id);trdFlash()}

/* patient explanations (admin) */
let trdIlg=null,trdIQ='';const trdIOpen=new Set();
function trdInfo(){
 const l=trdIlg||trdLg(),sl='block border rounded p-1.5 mt-1 text-xs font-bold normal-case bg-white text-slate-900',lab='block text-[10px] text-slate-500 font-bold uppercase';
 return `<p class="text-xs text-slate-500">These are the patient-friendly explanations used in the “About your treatments” message. Edit the wording for each language. Clear a text to return to the built-in version. Link a treatment to an explanation with the 🌐 button in the Treatments tab.</p>`
  +`<div class="np flex flex-wrap items-end gap-3 text-xs"><label class="${lab}">Language<select onchange="trdIlg=this.value;rTRD()" class="${sl}" data-notr>${LANGS.map(x=>`<option value="${x[0]}"${x[0]==l?' selected':''}>${x[1]}</option>`).join('')}</select></label>`
  +`<div class="grow min-w-[10rem]"><label class="${lab}">Search<input value="${esc(trdIQ)}" placeholder="Search explanations…" oninput="trdIQ=this.value;trdIList()" class="${sl} w-full"></label></div><button type="button" onclick="trdIAdd()" class="g rounded px-3 py-1.5 font-bold uppercase">+ Add Explanation</button>${(PDB.xd||[]).length?`<button type="button" onclick="trdIRs()" class="bg-slate-200 text-slate-800 rounded px-3 py-1.5 font-bold uppercase">${esc(ti('Bring back deleted explanations ({0})',PDB.xd.length))}</button>`:''}</div>`
  +`<div id="trdil" class="space-y-2">${trdIHtml(l)}</div>`}
function trdIHtml(l){
 const q=(trdIQ||'').trim().toLowerCase(),uses={};trdAll().forEach(({t})=>(t.e||[]).forEach(k=>uses[k]=(uses[k]||0)+1));
 return trdIK().map(k=>{const b=trdIB(k,l),o=PDB.io[k]||{},ed=!!((o.t&&o.t[l])||(o.x&&o.x[l]));
  if(q&&!((b.t+' '+b.x+' '+trdIL(k)).toLowerCase().includes(q)))return'';
  return `<details data-k="${k}" ${trdIOpen.has(k)?'open':''} ontoggle="trdITg(this)" class="rounded-xl border border-slate-200 bg-white"><summary class="cursor-pointer select-none px-3 py-2 text-xs font-bold flex flex-wrap justify-between gap-2"><span data-notr>${esc(b.t||trdIL(k))}</span><span class="text-[10px] text-slate-400">${esc(ti('Linked treatments: {0}',uses[k]||0))}${ed?' · <span class="text-amber-700">Edited</span>':''}</span></summary>`
   +`<div class="p-3 space-y-2"><input data-notr dir="auto" value="${esc(b.t)}" onchange="trdIO('${k}','t','${l}',this.value)" class="w-full border rounded p-1.5 text-xs font-bold bg-white"><textarea data-notr dir="auto" rows="8" onchange="trdIO('${k}','x','${l}',this.value)" class="w-full border rounded p-2 text-xs font-semibold">${esc(b.x)}</textarea>`
   +`<div class="np flex flex-wrap gap-2">${TRD_INFO[k]?`<button type="button" onclick="trdIR(this,'${k}','${l}')" class="bg-slate-200 rounded px-2 py-1 text-[10px] font-bold uppercase">Restore default</button><button type="button" data-xdel="${k}" onclick="trdIXd(this,'${k}')" class="bg-red-600 text-white rounded px-2 py-1 text-[10px] font-bold uppercase">${esc(ti('Delete'))}</button>`:`<button type="button" data-xdel="${k}" onclick="trdIDel(this,'${k}')" class="bg-red-600 text-white rounded px-2 py-1 text-[10px] font-bold uppercase">${esc(ti('Delete'))}</button>`}</div></div></details>`}).join('')||`<p class="text-xs text-slate-500 italic p-2">No explanations found.</p>`}
function trdIList(){const e=$('trdil');if(e)e.innerHTML=trdIHtml(trdIlg||trdLg())}
function trdITg(el){const k=el.dataset.k;el.open?trdIOpen.add(k):trdIOpen.delete(k)}
function trdIO(k,f,l,v){v=String(v).replace(/\r/g,'').trim();const o=PDB.io[k]=PDB.io[k]||{};o[f]=o[f]||{};
 const base=TRD_INFO[k]?(TRD_INFO[k][f]||[])[trdLn(l)]:'';
 if(!v||v===base)delete o[f][l];else o[f][l]=v;
 ['t','x'].forEach(g=>{if(o[g]&&!Object.keys(o[g]).length)delete o[g]});if(!Object.keys(o).length)delete PDB.io[k];
 trdSave();trdFlash();trdIList()}
function trdIR(b,k,l){trdTwo(b,'',()=>{const o=PDB.io[k];if(o){['t','x'].forEach(g=>{if(o[g])delete o[g][l];if(o[g]&&!Object.keys(o[g]).length)delete o[g]});if(!Object.keys(o).length)delete PDB.io[k]}trdSave();trdIList();trdFlash()})}
function trdIAdd(){const l=trdIlg||trdLg(),k='u'+Date.now().toString(36),n=ti('New explanation');PDB.ic.push({k,n});PDB.io[k]={t:{[l]:n},x:{[l]:ti('Write a short paragraph for the patient here.')}};trdIOpen.add(k);trdSave();rTRD();trdFlash()}
function trdIXd(b,k){trdTwo(b,'',()=>{if(!(PDB.xd||[]).includes(k)){PDB.xd=[...(PDB.xd||[]),k]}trdIOpen.delete(k);trdSave();rTRD();trdFlash()})}
function trdIRs(){PDB.xd=[];trdSave();rTRD();trdFlash()}
function trdIDel(b,k){trdTwo(b,'',()=>{PDB.ic=PDB.ic.filter(x=>x.k!=k);delete PDB.io[k];trdIOpen.delete(k);trdAll().forEach(({t})=>{if(t.e)t.e=t.e.filter(x=>x!=k)});trdSave();rTRD();trdFlash()})}

/* settings & criteria */
function trdSettings(){
 const R=trdRates(),auto=PDB.ratesMode!='manual',age=trdRAge(),sp=PDB.split,ip='class="w-24 border rounded p-1.5 text-xs font-bold bg-white text-right"',tp='class="grow min-w-[14rem] max-w-full border rounded p-1.5 text-xs font-bold bg-white"',
  row=(l,h,s)=>`<div class="flex flex-wrap items-center gap-2 py-1.5 border-b border-slate-100 text-xs"><span class="w-72 max-w-full font-bold text-slate-600">${l}</span>${h}${s?`<span class="text-[10px] text-slate-400">${s}</span>`:''}</div>`,
  card=(t,b)=>`<div class="rounded-xl border border-slate-200 bg-white p-4"><h3 class="lux font-bold text-sm border-b border-slate-200 pb-2 mb-2"><span class="text-[#a08a7c]">■</span> ${t}</h3>${b}</div>`,
  n=(k,v,x)=>`<input type="number" step="any" min="0" value="${v}" onchange="trdS('${k}',this.value${x?`,'${x}'`:''})" ${ip}>`;
 return `<div class="grid grid-cols-1 xl:grid-cols-2 gap-4">`
 +card('Currency rates (1 USD =)',`<div class="flex flex-wrap gap-2 mb-2">${[['auto','Automatic'],['manual','Manual']].map(([m,l])=>`<button type="button" onclick="trdS('rmode','${m}')" class="${(auto?'auto':'manual')==m?'g':'bg-slate-100 text-slate-700'} rounded px-3 py-1.5 text-[10px] font-bold uppercase">${l}</button>`).join('')}</div>`
   +(auto?`<p class="text-[10px] text-slate-500 mb-1">Rates are refreshed automatically every day from a market exchange-rate feed. Prices in the database are in USD.</p>`+(age!=null&&age>3?`<p class="text-[10px] font-bold text-amber-700 mb-1">${esc(ti('The rates were last refreshed {0} days ago and may be out of date.',age))}</p>`:'')+row('USD','<b class="w-24 text-right px-1.5">1</b>','')+TRD_CUR.filter(c=>c!='USD').map(c=>row(c,`<b class="w-24 text-right px-1.5" data-notr>${+(+R[c]).toFixed(6)}</b>`,'')).join('')+`<p class="text-[10px] text-slate-400 pt-2">${esc(ti('Last updated: {0}',TRD_LIVE.at))}</p>`
    :`<p class="text-[10px] text-slate-500 mb-1">Prices in the database are in USD. Update these rates whenever the exchange rates change.</p>`+row('USD','<b class="w-24 text-right px-1.5">1</b>','')+TRD_CUR.filter(c=>c!='USD').map(c=>row(c,n('rate',R[c],c),'')).join('')+`<p class="text-[10px] text-slate-400 pt-2">${esc(PDB.ratesAt?ti('Last updated: {0}',PDB.ratesAt):'')}</p>`))
 +card('Deposit',row('Deposit Amount',n('dep',PDB.deposit),'in the selected currency')+`<p class="text-[10px] text-slate-500 pt-2">This amount is taken out of the total before the rest is split into visits.</p>`)
 +card('Visit split (% of the amount after the deposit)',
   row('Two visits — first visit %',n('s2',sp[2][0]),esc(ti('Remaining: {0}%',100-sp[2][0])))
  +row('Three visits — first visit %',n('s3a',sp[3][0]),'')
  +row('Three visits — second visit %',n('s3b',sp[3][1]),esc(ti('Remaining: {0}%',100-sp[3][0]-sp[3][1])))
  +`<p class="text-[10px] text-slate-500 pt-2">The remaining share is the last visit, so the visits always add up exactly to the total.</p>`)
 +card('Promotion options',
   row('Promotion % — Custom Plan',`<input value="${esc(PDB.promoC.join(', '))}" onchange="trdS('pc',this.value)" ${tp}>`,'')
  +`<p class="text-[10px] text-slate-500 pt-2">Comma-separated numbers, e.g. 5, 10, 15. A promotion is refused when it would take the price below the Least Price.</p>`)
 +card('First-visit keywords',`<input value="${esc(PDB.kw.join(', '))}" onchange="trdS('kw',this.value)" class="w-full border rounded p-1.5 text-xs font-bold bg-white"><p class="text-[10px] text-slate-500 pt-2">Treatments whose name contains one of these words go into the first visit of the Treatment Explanation. All others go into the second visit.</p>`)
 +card('Package rules',row('All-on-4 — implants per jaw',n('pk',trcPkR().i4,'i4'),'')+row('All-on-6 — implants per jaw',n('pk',trcPkR().i6,'i6'),'')+row('Crowns per jaw',n('pk',trcPkR().cr,'cr'),'')+row('Bone graft / sinus lift — default quantity',n('pk',trcPkR().bs,'bs'),'')+`<p class="text-[10px] text-slate-500 pt-2">These numbers pre-fill the quantities in the All-on-4, All-on-6 and Zygomatic builders. The consultant can still change each quantity.</p>`)
 +`</div>`}
function trdS(k,v,x){
 const bad=m=>{trdFlash(ti(m),1);rTRD()};
 if(k=='rmode'){if(v=='manual'&&PDB.ratesMode!='manual')PDB.rates=trdRates();PDB.ratesMode=v=='manual'?'manual':'auto';PDB.ratesAt=new Date().toISOString().slice(0,10)}
 else if(k=='rate'){const n=trdNum(v);if(!(n>0))return bad('That value is not valid.');PDB.rates[x]=n;PDB.ratesAt=new Date().toISOString().slice(0,10)}
 else if(k=='dep'){const n=trdNum(v);if(n==null||n<0)return bad('That value is not valid.');PDB.deposit=n}
 else if(k=='s2'){const n=trdNum(v);if(!(n>=1&&n<=99))return bad('That value is not valid.');PDB.split[2]=[n]}
 else if(k=='s3a'||k=='s3b'){const n=trdNum(v),a=k=='s3a'?n:PDB.split[3][0],b=k=='s3b'?n:PDB.split[3][1];if(!(n>=1&&n<=98)||a+b>=100)return bad('The first two percentages must add up to less than 100.');PDB.split[3]=[a,b]}
 else if(k=='pn'||k=='pc'){const a=String(v).split(/[,;\s]+/).map(Number).filter(x=>x>0&&x<=100);if(!a.length)return bad('That value is not valid.');PDB[k=='pn'?'promoN':'promoC']=a}
 else if(k=='pk'){const n=trdNum(v);if(!(n>=1&&n<=99))return bad('That value is not valid.');PDB.pk=trcPkR();PDB.pk[x]=Math.round(n)}
 else if(k=='kw'){const a=String(v).split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);if(!a.length)return bad('That value is not valid.');PDB.kw=a}
 trdSave();rTRD();trdFlash()}

/* message templates */
let trdTL=null;
function trdTpl(){
 const l=trdTL||trdLg();
 return `<div class="flex flex-wrap items-end gap-3"><div class="grow min-w-[16rem] space-y-1"><p class="text-xs text-slate-500">These texts are used for the messages consultants copy to patients. Put a token such as {LIST} on its own line where a list of treatments or prices must appear.</p><p class="text-xs text-slate-500">Each language has its own text. The messages use the language chosen in the portal.</p><p class="text-xs text-slate-500">The dates {DATES} and {UNTIL} come from the sheet marked “Use in plans” in Appointment Planning; {UNTIL} is the month after the last available date. The nights {NIGHTSA}, {NIGHTSB} and {NIGHTSC} follow the hotel nights chosen in the calculator: 3 nights in the first visit, the rest in the following visits.</p></div><label class="block text-[10px] text-slate-500 font-bold uppercase">Language<select onchange="trdTL=this.value;rTRD()" data-notr class="block border rounded p-1.5 mt-1 text-xs font-bold normal-case bg-white text-slate-900">${LANGS.map(x=>`<option value="${x[0]}"${x[0]==l?' selected':''}>${x[1]}</option>`).join('')}</select></label></div>`
  +TRD_TPL.map(([k,t,tk])=>`<div class="rounded-xl border border-slate-200 bg-white p-3 space-y-1"><div class="flex flex-wrap justify-between items-center gap-2"><b class="text-xs uppercase text-slate-700">${t}</b><button type="button" onclick="trdTr(this,'${k}','${l}')" class="bg-slate-200 rounded px-2 py-1 text-[10px] font-bold uppercase">Restore default</button></div>${tk?`<p class="text-[10px] text-slate-400" data-notr>${esc(ti('Tokens: {0}',tk))}</p>`:''}<textarea data-notr dir="auto" rows="${k=='lb'?5:12}" onchange="trdT('${k}','${l}',this.value)" class="w-full border rounded p-2 text-xs font-semibold">${esc(trdTx(k,l))}</textarea></div>`).join('')}
function trdT(k,l,v){const d=(TRD_TX0[k]||{})[l]||'';PDB.tx[k]=PDB.tx[k]||{};if(String(v).trim()===''||v===d)delete PDB.tx[k][l];else PDB.tx[k][l]=v;if(!Object.keys(PDB.tx[k]).length)delete PDB.tx[k];trdSave();trdFlash()}
function trdTr(b,k,l){trdTwo(b,'',()=>{if(PDB.tx[k]){delete PDB.tx[k][l];if(!Object.keys(PDB.tx[k]).length)delete PDB.tx[k]}trdSave();rTRD();trdFlash()})}

/* Excel import / export */
function trdSheets(){
 const R=trdRates(),dbR=[['Category','Type','Category Description','Treatment','Base USD (Single for hotels)','Least Price (Double for hotels)','Normal Price (Triple for hotels)','Info blocks',...TRD_LC.map(l=>'Name '+l.toUpperCase()),'Package role','High Price']];
 PDB.cats.forEach(c=>{const ty=c.kind=='h'?'Hotel':'Treatment';if(!c.items.length)dbR.push([c.name,ty,c.d||'','',null,null,null]);c.items.forEach(t=>dbR.push([c.name,ty,c.d||'',t.n,t.b,t.l,t.x,(t.e||[]).join(', '),...TRD_LC.map(l=>(t.tn||{})[l]||''),trdPrL(t.p),c.kind=='h'||t.h==null?null:t.h]))});
 return{dbR,st:[['Setting','Value'],['Deposit',PDB.deposit],['Two visits - first %',PDB.split[2][0]],['Three visits - first %',PDB.split[3][0]],['Three visits - second %',PDB.split[3][1]],['Promotion % - Custom Plan',PDB.promoC.join(', ')],['First visit keywords',PDB.kw.join(', ')],['Implants per jaw - All-on-4',trcPkR().i4],['Implants per jaw - All-on-6',trcPkR().i6],['Crowns per jaw',trcPkR().cr],['Bone / sinus default quantity',trcPkR().bs],...TRD_CUR.filter(c=>c!='USD').map(c=>['Rate '+c,R[c]])],
  tp:[['Template','Language','Text'],...TRD_TPL.flatMap(([k])=>LANGS.map(x=>[k,x[0],trdTx(k,x[0])]))]}}
async function trdExp(){
 const dl=await kcDl();if(!dl)return trdFlash(ti('Saving files is not available in this view.'),1);
 try{const s=trdSheets(),wb=XLSX.utils.book_new();[['Data Base',s.dbR],['Settings',s.st],['Templates',s.tp]].forEach(([n,r])=>XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(r),n));
  await dl.save({filename:'EOP-Treatment-Database-'+new Date().toISOString().slice(0,10)+'.xlsx',data:new Blob([XLSX.write(wb,{type:'array',bookType:'xlsx'})],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})})}
 catch(e){if(!e||e.code!='declined')trdFlash(ti('Could not create the Excel file.'),1)}}
function trdParse(rows,merges,st,tp){
 const cell=v=>v==null?'':String(v).replace(/\s+/g,' ').trim(),
  num=v=>{if(v==null||String(v).trim()==='')return null;const n=typeof v=='number'?v:parseFloat(String(v).replace(/[^0-9.\-]/g,''));return isFinite(n)&&n>=0?n:null},
  h0=(rows[0]||[]).map(x=>cell(x).toLowerCase()),cats=[],out={cats,rates:null,st:null,tx:null,pr:false};
 if(h0.includes('category')&&h0.includes('treatment')){
  const ci=h0.indexOf('category'),ki=h0.indexOf('type'),di=h0.indexOf('category description'),ni=h0.indexOf('treatment'),ei=h0.indexOf('info blocks'),tni=TRD_LC.map(l=>h0.indexOf('name '+l)),pri=h0.indexOf('package role'),hi=h0.indexOf('high price');out.pr=pri>-1;
  rows.slice(1).forEach(r=>{const cn=cell(r[ci]);if(!cn)return;let c=cats.find(x=>x.name==cn);
   if(!c){c={name:cn,kind:ki>-1&&/hotel/i.test(cell(r[ki]))?'h':'t',d:di>-1?cell(r[di]):'',items:[]};cats.push(c)}
   const n=cell(r[ni]);if(n){const it={n,b:num(r[ni+1]),l:num(r[ni+2]),x:num(r[ni+3])};if(ei>-1)it.e=cell(r[ei]).split(/[,;]+/).map(z=>z.trim()).filter(Boolean);if(pri>-1)it.p=trdPrC(r[pri]);if(hi>-1&&c.kind!='h')it.h=num(r[hi]);if(tni.some(z=>z>-1)){it.tn={};TRD_LC.forEach((l,j)=>{const v=tni[j]>-1?cell(r[tni[j]]):'';if(v)it.tn[l]=v})}c.items.push(it)}})
 }else{
  const mg=new Set((merges||[]).filter(m=>m.s.r==m.e.r&&m.s.c==0&&m.e.c>=3).map(m=>m.s.r));let cur=null;const rt={};
  rows.forEach((r,ri)=>{
   if(ri<6&&TRD_CUR.includes(cell(r[6]))&&num(r[7])>0)rt[cell(r[6])]=num(r[7]);
   if(ri==0)return;const a=cell(r[0]);if(!a)return;
   if(mg.has(ri)){cur={name:a,kind:'t',d:'',items:[]};cats.push(cur);return}
   if(/^single$/i.test(cell(r[1]))&&/^double$/i.test(cell(r[2]))){if(cur)cur.kind='h';return}
   if(!cur){cur={name:'Treatments',kind:'t',d:'',items:[]};cats.push(cur)}
   cur.items.push({n:a,b:num(r[1]),l:num(r[2]),x:num(r[3])})});
  if(Object.keys(rt).length)out.rates=rt}
 if(st){const m={};st.slice(1).forEach(r=>{if(r&&r[0]!=null)m[cell(r[0])]=r[1]});
  const o={},n=k=>num(m[k]),lst=k=>String(m[k]==null?'':m[k]).split(/[,;\s]+/).map(Number).filter(x=>x>0&&x<=100);
  if(n('Deposit')!=null)o.deposit=n('Deposit');
  if(n('Two visits - first %')>=1&&n('Two visits - first %')<=99)o.s2=[n('Two visits - first %')];
  if(n('Three visits - first %')>=1&&n('Three visits - second %')>=1&&n('Three visits - first %')+n('Three visits - second %')<100)o.s3=[n('Three visits - first %'),n('Three visits - second %')];
  if(lst('Promotion % - Normal Price').length)o.promoN=lst('Promotion % - Normal Price');
  if(lst('Promotion % - Custom Plan').length)o.promoC=lst('Promotion % - Custom Plan');
  const kw=String(m['First visit keywords']||'').split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);if(kw.length)o.kw=kw;
  const rt=out.rates||{};TRD_CUR.filter(c=>c!='USD').forEach(c=>{if(n('Rate '+c)>0)rt[c]=n('Rate '+c)});if(Object.keys(rt).length)out.rates=rt;
  const pk={};[['i4','Implants per jaw - All-on-4'],['i6','Implants per jaw - All-on-6'],['cr','Crowns per jaw'],['bs','Bone / sinus default quantity']].forEach(([z,nm])=>{const v=n(nm);if(v!=null&&v>=1&&v<=99)pk[z]=Math.round(v)});if(Object.keys(pk).length)o.pk=pk;
  out.st=o}
 if(tp){const t={};tp.slice(1).forEach(r=>{if(!r||r[0]==null)return;const k0=cell(r[0]);let k=k0,l='en',v=r[1];if(r.length>=3&&LANGS.some(x=>x[0]==cell(r[1]))){l=cell(r[1]);v=r[2]}else if(k0=='expOneF'){k='expOne';l='fr'}else if(k0=='expMultiF'){k='expMulti';l='fr'}
   if(TRD_TPL.some(x=>x[0]==k)&&v!=null&&String(v)!=='')(t[k]=t[k]||{})[l]=trdMigV(k,l,String(v))});if(Object.keys(t).length)out.tx=t}
 if(!out.pr)out.cats=trdDropLegacy(cats);
 out.n=out.cats.reduce((s,c)=>s+c.items.length,0);
 return out}
function trdFile(inp){
 const f=inp.files&&inp.files[0];inp.value='';if(!f)return;const fr=new FileReader();
 fr.onload=()=>{try{
  const wb=XLSX.read(fr.result,{type:'array'}),g=n=>{const k=wb.SheetNames.find(x=>x.toLowerCase()==n);return k?wb.Sheets[k]:null},
   rw=(w,h)=>XLSX.utils.sheet_to_json(w,{header:1,defval:null,raw:true}),ws=g('data base')||wb.Sheets[wb.SheetNames[0]],s=g('settings'),t=g('templates');
  trdPend=trdParse(rw(ws),ws['!merges'],s?rw(s):null,t?rw(t):null);
  if(!trdPend.n){trdPend=null;return trdFlash(ti('Nothing was found in this file.'),1)}
  trdPendShow()}catch(e){trdPend=null;trdFlash(ti('Could not read this file. Use the Excel file exported from this page or your Data Base sheet.'),1)}};
 fr.readAsArrayBuffer(f)}
function trdPendShow(){const e=$('trdm');if(!e)return;if(!trdPend)return;
 e.className='np text-xs font-bold text-slate-800 bg-amber-50 border border-amber-300 rounded-lg p-2 flex flex-wrap items-center gap-2';
 e.innerHTML=`<span>${esc(ti('Replace the current database with the file? It contains {0} treatments in {1} categories.',trdPend.n,trdPend.cats.length))}</span><button type="button" onclick="trdApply()" class="g rounded px-3 py-1 uppercase">Replace</button><button type="button" onclick="trdPend=null;trdFlash('')" class="bg-slate-200 rounded px-3 py-1 uppercase">Cancel</button>`}
function trdApply(){const p=trdPend;if(!p)return;trdPend=null;
 const old=new Map(),oc=new Map();trdAll().forEach(({t})=>{if(!old.has(t.n))old.set(t.n,t)});PDB.cats.forEach(c=>oc.set(c.name,c));
 TRD_SEED.forEach(c=>{if(!oc.has(c.name))oc.set(c.name,c);c.items.forEach(t=>{if(!old.has(t.n))old.set(t.n,t)})});
 PDB.cats=p.cats.map((c,i)=>({id:'c'+Date.now().toString(36)+i,name:c.name,kind:c.kind,d:c.d||'',tn:{...((oc.get(c.name)||{}).tn||{})},items:c.items.map((t,j)=>{const q=old.get(t.n)||{};const pp=t.p!==undefined?t.p:q.p,hh=t.h!==undefined?t.h:q.h!==undefined?q.h:trdHi(t.n);return{id:trdUid()+j,n:t.n,b:t.b,l:t.l,x:t.x,...(hh>0?{h:hh}:hh===null?{h:null}:{}),e:t.e!==undefined?t.e:(q.e||[]).slice(),tn:{...(q.tn||{}),...(t.tn||{})},...(pp?{p:pp}:{})}})}));
 if(p.rates){PDB.rates={...PDB.rates,...p.rates,USD:1};PDB.ratesAt=new Date().toISOString().slice(0,10)}
 if(p.st){const s=p.st;if(s.deposit!=null)PDB.deposit=s.deposit;if(s.s2)PDB.split[2]=s.s2;if(s.s3)PDB.split[3]=s.s3;if(s.promoN)PDB.promoN=s.promoN;if(s.promoC)PDB.promoC=s.promoC;if(s.kw)PDB.kw=s.kw;if(s.pk)PDB.pk={...trcPkR(),...s.pk}}
 if(p.tx)Object.keys(p.tx).forEach(k=>{PDB.tx[k]={...(PDB.tx[k]||{}),...p.tx[k]}});
 trdSave();rTRD();trdFlash(ti('Imported {0} treatments in {1} categories.',p.n,p.cats.length))}
function trdImp(){const i=$('trdf');if(i)i.click()}
function trdRst(b){trdTwo(b,'',()=>{PDB=trdDef();trdSave();trdPend=null;rTRD();trdFlash(ti('Starter data restored.'))})}
